fn qm31_sum_products_small<const N: usize>(left: [QM31; N], right: [QM31; N]) -> QM31 {
    debug_assert!(N >= 2 && N <= 4);
    // [quadratic-extension component][CM31 Karatsuba channel].
    let mut sums = [[0u64; 3]; 3];
    let mut index = 0usize;
    while index < N {
        sums = qm31_accumulate_product_channels(sums, left[index], right[index]);
        index += 1;
    }

    qm31_from_karatsuba_channel_sums(sums)
}

pub fn qm31_sum_products3(left: [QM31; 3], right: [QM31; 3]) -> QM31 {
    qm31_sum_products_small(left, right)
}

pub fn evaluate_state_only_polynomial(
    polynomial: &StateOnlySumcheckPolynomial,
    challenge: QM31,
) -> QM31 {
    let x2 = challenge.square();
    let x3 = challenge.mul(x2);
    let x4 = x2.square();
    let powers = [challenge, x2, x3];
    let prepared_x4 = PreparedQm31Multiplier::new(x4);
    let block_value = |block: usize| {
        let start = 4 * block;
        polynomial[start].add(qm31_sum_products3(
            powers,
            [
                polynomial[start + 1],
                polynomial[start + 2],
                polynomial[start + 3],
            ],
        ))
    };
    let mut accumulator = block_value(6);
    let mut block = 6usize;
    while block > 0 {
        block -= 1;
        accumulator = prepared_x4.mul(accumulator).add(block_value(block));
    }
    accumulator
}
